/* ------------------------------- HOOKS ------------------------------- */

function usePrefersReducedMotion() {
  const [reduced, setReduced] = useState(false);
  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    setReduced(mq.matches);
    const handler = (e) => setReduced(e.matches);
    mq.addEventListener("change", handler);
    return () => mq.removeEventListener("change", handler);
  }, []);
  return reduced;
}

function useRevealOnScroll() {
  const ref = useRef(null);
  const [visible, setVisible] = useState(false);
  const reduced = usePrefersReducedMotion();
  useEffect(() => {
    if (reduced) { setVisible(true); return; }
    const el = ref.current;
    if (!el) return;
    const obs = new IntersectionObserver(([entry]) => {
      if (entry.isIntersecting) { setVisible(true); obs.disconnect(); }
    }, { threshold: 0.16 });
    obs.observe(el);
    return () => obs.disconnect();
  }, [reduced]);
  return [ref, visible];
}

function Reveal({ as: Tag = "div", className = "", delay = 0, children, ...rest }) {
  const [ref, visible] = useRevealOnScroll();
  return (
    <Tag ref={ref} className={"reveal " + (visible ? "reveal-visible " : "") + className} style={{ transitionDelay: visible ? delay + "ms" : "0ms" }} {...rest}>
      {children}
    </Tag>
  );
}

/* -------------------------------- HEADER ------------------------------- */

function Header({ page, goTo }) {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);
  const menuButtonRef = useRef(null);
  const firstMenuLinkRef = useRef(null);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 12);
    onScroll();
    window.addEventListener("scroll", onScroll, { passive: true });
    return () => window.removeEventListener("scroll", onScroll);
  }, []);

  useEffect(() => {
    if (menuOpen) {
      document.body.style.overflow = "hidden";
      firstMenuLinkRef.current?.focus();
      const onKey = (e) => { if (e.key === "Escape") { setMenuOpen(false); menuButtonRef.current?.focus(); } };
      window.addEventListener("keydown", onKey);
      return () => { document.body.style.overflow = ""; window.removeEventListener("keydown", onKey); };
    }
  }, [menuOpen]);

  const handleNav = (id) => { goTo(id); setMenuOpen(false); };
  const isActive = (id) => (id === "modalidades" ? page === "modalidades" || page.startsWith("modalidades/") : page === id);

  return (
    <>
      <header className={"site-header" + (scrolled ? " site-header--scrolled" : "")}>
        <div className="site-header__inner">
          <button className="logo-btn" onClick={() => handleNav("inicio")} aria-label="Eloqua English School — ir para o início">
            <img src={LOGO_PRIMARY} alt="Eloqua English School" className="logo-img" />
          </button>

          <nav className="nav-desktop" aria-label="Navegação principal">
            <ul>
              {NAV_ITEMS.map((item) => (
                <li key={item.id}>
                  <button className={"nav-link" + (isActive(item.id) ? " nav-link--active" : "")} aria-current={isActive(item.id) ? "page" : undefined} onClick={() => handleNav(item.id)}>
                    {item.label}
                  </button>
                </li>
              ))}
            </ul>
          </nav>

          <div className="header-actions">
            <a className="btn btn--purple btn--sm" href={CONTACT.whatsappUrl} target="_blank" rel="noopener noreferrer">Conversar com a Eloqua</a>
            <button ref={menuButtonRef} className="menu-toggle" aria-expanded={menuOpen} aria-controls="mobile-menu" aria-label={menuOpen ? "Fechar menu" : "Abrir menu"} onClick={() => setMenuOpen((v) => !v)}>
              {menuOpen ? <X size={22} /> : <Menu size={22} />}
            </button>
          </div>
        </div>
      </header>

      {menuOpen && (
        <div className="mobile-menu" id="mobile-menu" role="dialog" aria-modal="true" aria-label="Menu de navegação">
          <nav className="mobile-menu__nav" aria-label="Navegação principal (celular)">
            <ul>
              {NAV_ITEMS.map((item, i) => (
                <li key={item.id}>
                  <button ref={i === 0 ? firstMenuLinkRef : null} className={"mobile-nav-link" + (isActive(item.id) ? " mobile-nav-link--active" : "")} onClick={() => handleNav(item.id)}>
                    {item.label}
                  </button>
                </li>
              ))}
            </ul>
          </nav>
          <div className="mobile-menu__footer">
            <a className="btn btn--purple" href={CONTACT.whatsappUrl} target="_blank" rel="noopener noreferrer">Conversar com a Eloqua</a>
          </div>
        </div>
      )}
    </>
  );
}

