/* Bloco visual sofisticado para espaços que ainda aguardam fotografia
   real — usa ativos reais da própria Eloqua (logo, ELO HUB ou Semester
   Report) em vez de uma caixa vazia com texto entre colchetes. */
function BrandPlaceholder({ phrase, tone = "green", asset = "logo" }) {
  return (
    <div className={"brand-placeholder brand-placeholder--" + tone}>
      {asset === "elohub" ? (
        <img src={ELO_HUB_HERO_IMAGE} alt="" aria-hidden="true" className="brand-placeholder__asset" />
      ) : asset === "report" ? (
        <img src={SEMESTER_REPORT_CARD_IMAGE} alt="" aria-hidden="true" className="brand-placeholder__asset brand-placeholder__asset--report" />
      ) : (
        <img src={LOGO_PRIMARY} alt="" aria-hidden="true" className="brand-placeholder__logo" />
      )}
      <p className="brand-placeholder__phrase">{phrase}</p>
    </div>
  );
}

/* Card editorial grande — logo + frase principal + frase secundária.
   Usado como composição visual de destaque em páginas internas. */
function BrandEditorialCard({ heading, subtext, tone = "green" }) {
  return (
    <div className={"brand-editorial-card brand-editorial-card--" + tone}>
      <img src={LOGO_PRIMARY} alt="Eloqua English School" className="brand-editorial-card__logo" />
      <p className="brand-editorial-card__heading">{heading}</p>
      <p className="brand-editorial-card__subtext">{subtext}</p>
    </div>
  );
}

/* Linha de FAQ acessível: expande/recolhe com clique ou teclado, e o
   texto da pergunta já fica totalmente legível no estado fechado. */
function FaqItem({ q, a, defaultOpen = false }) {
  const [open, setOpen] = useState(defaultOpen);
  return (
    <div className="faq-item">
      <button
        className="faq-item__trigger"
        aria-expanded={open}
        onClick={() => setOpen((v) => !v)}
      >
        <span>{q}</span>
        <ChevronDown size={20} aria-hidden="true" className={"faq-item__chevron" + (open ? " faq-item__chevron--open" : "")} />
      </button>
      {open && <p className="faq-item__answer">{a}</p>}
    </div>
  );
}

