/* --------------------------------- APP --------------------------------- */

const PAGES = {
  inicio: HomePage,
  "como-funciona": ComoFuncionaPage,
  modalidades: ModalidadesIndexPage,
  "modalidades/eloqua-signature": SignaturePage,
  "modalidades/mini-groups": MiniGroupsPage,
  sobre: SobrePage,
  resultados: ResultadosPage,
  contato: ContatoPage,
};

export default function App() {
  const [page, setPage] = useState("inicio");
  const goTo = useCallback((id) => setPage(id), []);

  useEffect(() => {
    const meta = PAGE_META[page] || PAGE_META.inicio;
    document.title = meta.title;
    let tag = document.querySelector('meta[name="description"]');
    if (!tag) { tag = document.createElement("meta"); tag.name = "description"; document.head.appendChild(tag); }
    tag.content = meta.description;
    window.scrollTo({ top: 0, behavior: "instant" in window ? "instant" : "auto" });
  }, [page]);

  useEffect(() => {
    if (page !== "inicio") return;
    const ld = document.createElement("script");
    ld.type = "application/ld+json";
    ld.text = JSON.stringify({
      "@context": "https://schema.org",
      "@type": "EducationalOrganization",
      name: "Eloqua English School",
      url: "https://eloquaenglish.com.br",
      slogan: "Do inglês que você entende ao inglês que você consegue falar.",
      areaServed: "BR",
      founder: { "@type": "Person", name: "Rayane Portes" },
    });
    document.head.appendChild(ld);
    return () => document.head.removeChild(ld);
  }, [page]);

  const PageComponent = PAGES[page] || HomePage;

  return (
    <div className="eloqua-app">
      <GlobalStyles />
      <a href="#main-content" className="skip-link">Pular para o conteúdo</a>
      <Header page={page} goTo={goTo} />
      <main id="main-content" tabIndex={-1}>
        <PageComponent goTo={goTo} />
      </main>
      <Footer goTo={goTo} />
    </div>
  );
}

